-- Synthetic historical order parents from original Node exporter - not an order importer.
CREATE TABLE `jm_transfer_orders` (
  `id` LONGTEXT NULL,
  `code` LONGTEXT NULL,
  `request_id` LONGTEXT NULL,
  `request_hash` LONGTEXT NULL,
  `access_hash` LONGTEXT NULL,
  `snapshot` JSON NULL,
  `contact` JSON NULL,
  `booking_status` LONGTEXT NULL,
  `payment_status` LONGTEXT NULL,
  `instructions` LONGTEXT NULL,
  `version` BIGINT NULL,
  `created_at` DATETIME(6) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
